Item.method_code:
Item _variable = this.newItem("Variable", "get");
_variable.setID(this.getID());
_variable.setAttribute("select", "value");
_variable.setAttribute("levels", "0");
_variable.setAttribute("config_path", "");
_variable = _variable.apply();
if (!_variable.isError())
{
	string oldItemValue = _variable.getProperty("value");
	if (oldItemValue == null && this.getProperty("value", null) == null)
		this.setProperty("value", this.getProperty("default_value", null));	
}
return this;
